-- Communications C1 (docs/communications-c1.md): unified activity extensions, conversations and
-- immutable historical messages. Generated by `prisma migrate diff`, then the constraints, guards,
-- grants and RLS Prisma cannot express were added by hand (sections marked "hand-written").
--
-- Ordering: depends only on 20261114050000_customers (activities, customers, contacts) and
-- 20261113150000_tenancy (businesses). It references no finance, sales, projects, people or
-- scheduling object, so it may be applied before or after 20261118000000_people and any scheduling
-- migration. Existing activity rows get visibility STANDARD and satisfy every new CHECK.
-- Nothing here sends anything: there is no provider, no delivery state and no source value that
-- means "sent by Business OS".

-- AlterTable
ALTER TABLE "activities" ADD COLUMN     "conversation_id" UUID,
ADD COLUMN     "edited_at" TIMESTAMPTZ,
ADD COLUMN     "message_id" UUID,
ADD COLUMN     "visibility" TEXT NOT NULL DEFAULT 'STANDARD';

-- CreateTable
CREATE TABLE "conversations" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "channel" TEXT NOT NULL,
    "subject" TEXT,
    "customer_id" UUID,
    "contact_id" UUID,
    "source" TEXT NOT NULL DEFAULT 'MANUAL',
    "external_source" TEXT,
    "external_thread_id" TEXT,
    "created_by_id" UUID NOT NULL,
    "last_message_at" TIMESTAMPTZ,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "conversations_pkey" PRIMARY KEY ("business_id","id")
);

-- CreateTable
CREATE TABLE "messages" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "conversation_id" UUID NOT NULL,
    "direction" TEXT NOT NULL,
    "source" TEXT NOT NULL,
    "occurred_at" TIMESTAMPTZ NOT NULL,
    "recorded_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "recorded_by_id" UUID NOT NULL,
    "subject" TEXT,
    "body" TEXT,
    "external_source" TEXT,
    "external_message_id" TEXT,
    "content_hash" CHAR(64) NOT NULL,

    CONSTRAINT "messages_pkey" PRIMARY KEY ("business_id","id")
);

-- CreateTable
CREATE TABLE "message_participants" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "message_id" UUID NOT NULL,
    "role" TEXT NOT NULL,
    "position" SMALLINT NOT NULL,
    "display_name" TEXT,
    "address" TEXT,
    "contact_id" UUID,
    "user_id" UUID,

    CONSTRAINT "message_participants_pkey" PRIMARY KEY ("business_id","id")
);

-- CreateIndex
CREATE INDEX "conversations_business_id_customer_id_created_at_id_idx" ON "conversations"("business_id", "customer_id", "created_at" DESC, "id");

-- CreateIndex
CREATE INDEX "conversations_business_id_contact_id_created_at_id_idx" ON "conversations"("business_id", "contact_id", "created_at" DESC, "id");

-- CreateIndex
CREATE INDEX "conversations_business_id_created_at_id_idx" ON "conversations"("business_id", "created_at" DESC, "id");

-- CreateIndex
CREATE INDEX "messages_business_id_conversation_id_occurred_at_id_idx" ON "messages"("business_id", "conversation_id", "occurred_at", "id");

-- CreateIndex
CREATE UNIQUE INDEX "messages_conversation_link_key" ON "messages"("business_id", "conversation_id", "id");

-- CreateIndex
CREATE INDEX "message_participants_business_id_contact_id_idx" ON "message_participants"("business_id", "contact_id");

-- CreateIndex
CREATE UNIQUE INDEX "message_participants_business_id_message_id_role_position_key" ON "message_participants"("business_id", "message_id", "role", "position");

-- AddForeignKey
ALTER TABLE "conversations" ADD CONSTRAINT "conversations_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "conversations" ADD CONSTRAINT "conversations_customer_fkey" FOREIGN KEY ("business_id", "customer_id") REFERENCES "customers"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

