ALTER TABLE "message_participants" ADD CONSTRAINT "message_participants_message_fkey" FOREIGN KEY ("business_id", "message_id") REFERENCES "messages"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

