ALTER TABLE "message_participants" ADD CONSTRAINT "message_participants_contact_fkey" FOREIGN KEY ("business_id", "contact_id") REFERENCES "contacts"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

