ALTER TABLE "activities" ADD CONSTRAINT "activities_conversation_fkey" FOREIGN KEY ("business_id", "conversation_id") REFERENCES "conversations"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "activities" ADD CONSTRAINT "activities_message_fkey" FOREIGN KEY ("business_id", "conversation_id", "message_id") REFERENCES "messages"("business_id", "conversation_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;


-- =============================================================================================
-- Hand-written: constraints, guards, grants and RLS.
-- SQLSTATE class CM (communications): CM001 identity fixed, CM002 message history is read-only,
-- CM003 system activity cannot be removed, CM004 message dated in the future.
-- =============================================================================================

-- ---- activities (extended) -------------------------------------------------------------------
ALTER TABLE "activities"
  ADD CONSTRAINT activities_visibility_values CHECK ("visibility" IN ('STANDARD', 'RESTRICTED')),
  -- Only notes can be restricted; system and message entries are always standard.
  ADD CONSTRAINT activities_restricted_notes_only CHECK ("visibility" = 'STANDARD' OR "type" = 'note'),
  -- A message entry names both its conversation and its message, and only message entries do.
  ADD CONSTRAINT activities_message_link_pair CHECK (("conversation_id" IS NULL) = ("message_id" IS NULL)),
  ADD CONSTRAINT activities_message_link_type CHECK (("type" = 'message.recorded') = ("message_id" IS NOT NULL));
-- One timeline entry per recorded message.
CREATE UNIQUE INDEX "activities_message_key" ON "activities" ("business_id", "message_id") WHERE "message_id" IS NOT NULL;

-- Authorship, type, links, visibility and timestamps are fixed once written. Only a live note's
-- subject and body may be edited (edited_at is stamped here), and only a user-entered activity may
-- be removed, once. Column grants below say the same for bos_app; this holds for every role.
CREATE FUNCTION activities_guard_update() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF (NEW.id, NEW.business_id, NEW.type, NEW.occurred_at, NEW.actor_type, NEW.actor_user_id, NEW.customer_id, NEW.contact_id,
      NEW.data, NEW.schema_version, NEW.created_at, NEW.visibility, NEW.conversation_id, NEW.message_id)
     IS DISTINCT FROM
     (OLD.id, OLD.business_id, OLD.type, OLD.occurred_at, OLD.actor_type, OLD.actor_user_id, OLD.customer_id, OLD.contact_id,
      OLD.data, OLD.schema_version, OLD.created_at, OLD.visibility, OLD.conversation_id, OLD.message_id) THEN
    RAISE EXCEPTION 'activity identity is fixed' USING ERRCODE = 'CM001';
  END IF;
  IF OLD.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'removed activities are final' USING ERRCODE = 'CM001';
  END IF;
  IF NEW.deleted_at IS NOT NULL THEN
    IF position('.' in OLD.type) > 0 THEN
      RAISE EXCEPTION 'system activities cannot be removed' USING ERRCODE = 'CM003';
    END IF;
    IF (NEW.subject, NEW.body) IS DISTINCT FROM (OLD.subject, OLD.body) THEN
      RAISE EXCEPTION 'removal changes nothing else' USING ERRCODE = 'CM001';
    END IF;
    NEW.edited_at := OLD.edited_at;
    RETURN NEW;
  END IF;
  IF (NEW.subject, NEW.body) IS DISTINCT FROM (OLD.subject, OLD.body) THEN
    IF OLD.type <> 'note' THEN
      RAISE EXCEPTION 'only notes can be edited' USING ERRCODE = 'CM001';
    END IF;
    NEW.edited_at := now();
  ELSE
    NEW.edited_at := OLD.edited_at;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER activities_guard_update BEFORE UPDATE ON "activities" FOR EACH ROW EXECUTE FUNCTION activities_guard_update();

-- ---- conversations ---------------------------------------------------------------------------
ALTER TABLE "conversations"
  ADD CONSTRAINT conversations_channel_values CHECK ("channel" IN ('EMAIL', 'PHONE', 'SMS', 'CHAT', 'SOCIAL', 'IN_PERSON', 'OTHER')),
  ADD CONSTRAINT conversations_source_values CHECK ("source" IN ('MANUAL', 'IMPORT')),
  ADD CONSTRAINT conversations_subject_length CHECK ("subject" IS NULL OR char_length(btrim("subject")) BETWEEN 1 AND 300),
  ADD CONSTRAINT conversations_linked CHECK ("customer_id" IS NOT NULL OR "contact_id" IS NOT NULL),
  ADD CONSTRAINT conversations_external_pair CHECK (("external_source" IS NULL) = ("external_thread_id" IS NULL)),
  ADD CONSTRAINT conversations_external_format CHECK (
    "external_source" IS NULL OR ("external_source" ~ '^[a-z0-9][a-z0-9._-]{0,63}$' AND char_length("external_thread_id") BETWEEN 1 AND 512));
CREATE UNIQUE INDEX "conversations_external_key" ON "conversations" ("business_id", "external_source", "external_thread_id") WHERE "external_thread_id" IS NOT NULL;

CREATE FUNCTION conversations_guard_update() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF (NEW.id, NEW.business_id, NEW.channel, NEW.subject, NEW.customer_id, NEW.contact_id, NEW.source, NEW.external_source,
      NEW.external_thread_id, NEW.created_by_id, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.business_id, OLD.channel, OLD.subject, OLD.customer_id, OLD.contact_id, OLD.source, OLD.external_source,
      OLD.external_thread_id, OLD.created_by_id, OLD.created_at) THEN
    RAISE EXCEPTION 'conversation identity is fixed' USING ERRCODE = 'CM001';
  END IF;
  -- last_message_at only moves forward (C1-01): an older or null value never replaces a newer one,
  -- whatever order concurrent writers commit in.
  IF OLD.last_message_at IS NOT NULL AND (NEW.last_message_at IS NULL OR NEW.last_message_at < OLD.last_message_at) THEN
    NEW.last_message_at := OLD.last_message_at;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER conversations_guard_update BEFORE UPDATE ON "conversations" FOR EACH ROW EXECUTE FUNCTION conversations_guard_update();

-- ---- messages (read-only history) ------------------------------------------------------------
ALTER TABLE "messages"
  ADD CONSTRAINT messages_direction_values CHECK ("direction" IN ('INBOUND', 'OUTBOUND', 'INTERNAL')),
  -- MANUAL = a person recorded it; IMPORT = brought in from an export with its external id. There is
  -- deliberately no value meaning "sent by Business OS".
  ADD CONSTRAINT messages_source_values CHECK ("source" IN ('MANUAL', 'IMPORT')),
  ADD CONSTRAINT messages_subject_length CHECK ("subject" IS NULL OR char_length("subject") <= 300),
  ADD CONSTRAINT messages_body_length CHECK ("body" IS NULL OR char_length("body") <= 100000),
  ADD CONSTRAINT messages_has_content CHECK ("subject" IS NOT NULL OR "body" IS NOT NULL),
  ADD CONSTRAINT messages_external_pair CHECK (("external_source" IS NULL) = ("external_message_id" IS NULL)),
  ADD CONSTRAINT messages_external_format CHECK (
    "external_source" IS NULL OR ("external_source" ~ '^[a-z0-9][a-z0-9._-]{0,63}$' AND char_length("external_message_id") BETWEEN 1 AND 512)),
  ADD CONSTRAINT messages_import_has_external_id CHECK ("source" <> 'IMPORT' OR "external_message_id" IS NOT NULL),
  ADD CONSTRAINT messages_content_hash_format CHECK ("content_hash" ~ '^[0-9a-f]{64}$');
-- Idempotent import: one message per external id per business.
CREATE UNIQUE INDEX "messages_external_key" ON "messages" ("business_id", "external_source", "external_message_id") WHERE "external_message_id" IS NOT NULL;

-- recorded_at is database time, never client input; a historical message cannot be dated ahead.
CREATE FUNCTION messages_stamp_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  NEW.recorded_at := now();
  IF NEW.occurred_at > now() + interval '1 day' THEN
    RAISE EXCEPTION 'message dated in the future' USING ERRCODE = 'CM004';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER messages_stamp_insert BEFORE INSERT ON "messages" FOR EACH ROW EXECUTE FUNCTION messages_stamp_insert();

CREATE FUNCTION communications_read_only() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  RAISE EXCEPTION 'message history is read-only' USING ERRCODE = 'CM002';
END $$;
CREATE TRIGGER messages_read_only BEFORE UPDATE ON "messages" FOR EACH ROW EXECUTE FUNCTION communications_read_only();

-- ---- message_participants (read-only history) ------------------------------------------------
ALTER TABLE "message_participants"
  ADD CONSTRAINT message_participants_role_values CHECK ("role" IN ('FROM', 'TO', 'CC', 'BCC')),
  ADD CONSTRAINT message_participants_position_range CHECK ("position" BETWEEN 0 AND 499),
  ADD CONSTRAINT message_participants_name_length CHECK ("display_name" IS NULL OR char_length(btrim("display_name")) BETWEEN 1 AND 200),
  ADD CONSTRAINT message_participants_address_length CHECK ("address" IS NULL OR char_length(btrim("address")) BETWEEN 1 AND 320),
  ADD CONSTRAINT message_participants_identified CHECK (
    "display_name" IS NOT NULL OR "address" IS NOT NULL OR "contact_id" IS NOT NULL OR "user_id" IS NOT NULL);
CREATE TRIGGER message_participants_read_only BEFORE UPDATE ON "message_participants" FOR EACH ROW EXECUTE FUNCTION communications_read_only();

-- ---- least privilege ---------------------------------------------------------------------------
-- No DELETE anywhere: removal of an activity is a soft delete, message history is read-only, and
-- erasure arrives with its own reviewed privileged path (docs/communications-c1.md §7).
REVOKE ALL ON "conversations", "messages", "message_participants" FROM bos_app;
GRANT SELECT, INSERT ON "conversations", "messages", "message_participants" TO bos_app;
GRANT UPDATE ("last_message_at", "updated_at") ON "conversations" TO bos_app;
GRANT UPDATE ("subject", "body") ON "activities" TO bos_app;

-- ---- row-level security --------------------------------------------------------------------------
ALTER TABLE "conversations" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "conversations" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "conversations" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
-- Defence in depth for authorship: a row is created by the user of the unit of work.
CREATE POLICY created_by_session_user ON "conversations" AS RESTRICTIVE FOR INSERT TO bos_app
  WITH CHECK ("created_by_id" = nullif(current_setting('app.user_id', true), '')::uuid);

ALTER TABLE "messages" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "messages" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "messages" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
CREATE POLICY recorded_by_session_user ON "messages" AS RESTRICTIVE FOR INSERT TO bos_app
  WITH CHECK ("recorded_by_id" = nullif(current_setting('app.user_id', true), '')::uuid);

ALTER TABLE "message_participants" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "message_participants" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "message_participants" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
